    "id": "c-pds-preprocessor",
    "subjectId": "Programming & Data Structures",
    "chapterId": "pds-c-programming",
    "label": "C Preprocessor Directives & Macro Expansion Traps",
    "name": "C Preprocessor",
    "category": "C Programming Fundamentals",
    "kind": "definition",
    "summary": "Preprocessor runs before compilation to perform textual replacement (`#define`), file inclusion (`#include`), and conditional compilation (`#ifdef`, `#ifndef`). Macro arguments are replaced textually without type checking; missing parentheses cause operator precedence bugs.",
    "formula": "\\text{Macro Expansion: Textual token substitution WITHOUT evaluating expressions}",
    "keyFormulae": [
      "\\text{Macro with arguments: } \\texttt{#define SQUARE(x) ((x) * (x))}",
      "\\text{Stringizing Operator (\\#): Converts macro parameter to string literal: } \\texttt{#define STR(x) #x}",
      "\\text{Token-Pasting Operator (\\#\\#): Concatenates two tokens: } \\texttt{#define CONCAT(a, b) a##b}"
    ],
