    "id": "c-ga-direction-distance",
    "subjectId": "General Aptitude",
    "chapterId": "ga-analytical",
    "label": "Direction Sense, Cardinal/Ordinal Directions, Shadows & Pythagorean Displacement",
    "name": "Direction Sense & Displacement",
