    "imageUrl": "<svg viewBox=\"0 0 460 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"460\" height=\"120\" rx=\"12\" fill=\"#0F172A\"/><rect x=\"25\" y=\"20\" width=\"190\" height=\"75\" rx=\"8\" fill=\"#1E293B\" stroke=\"#38BDF8\" stroke-width=\"1.5\"/><text x=\"120\" y=\"45\" fill=\"#38BDF8\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Pie Degree to %</text><text x=\"120\" y=\"70\" fill=\"#22C55E\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">% = Degrees / 3.6</text><rect x=\"245\" y=\"20\" width=\"190\" height=\"75\" rx=\"8\" fill=\"#1E293B\" stroke=\"#22C55E\" stroke-width=\"1.5\"/><text x=\"340\" y=\"45\" fill=\"#22C55E\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Percentage Growth</text><text x=\"340\" y=\"70\" fill=\"#22C55E\" font-size=\"10\" text-anchor=\"middle\">[(Final - Initial)/Initial] \u00d7 100</text></svg>",
