    "imageUrl": "<svg viewBox=\"0 0 460 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"460\" height=\"120\" rx=\"12\" fill=\"#0F172A\"/><rect x=\"25\" y=\"20\" width=\"125\" height=\"85\" rx=\"6\" fill=\"#1E293B\" stroke=\"#38BDF8\" stroke-width=\"1.5\"/><text x=\"87\" y=\"45\" fill=\"#38BDF8\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">PROM</text><text x=\"87\" y=\"72\" fill=\"#CBD5E1\" font-size=\"10\" text-anchor=\"middle\">Fixed AND (Dec)</text><text x=\"87\" y=\"90\" fill=\"#22C55E\" font-size=\"9\" text-anchor=\"middle\">Prog OR</text><rect x=\"165\" y=\"20\" width=\"125\" height=\"85\" rx=\"6\" fill=\"#1E293B\" stroke=\"#F59E0B\" stroke-width=\"1.5\"/><text x=\"227\" y=\"45\" fill=\"#F59E0B\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">PAL</text><text x=\"227\" y=\"72\" fill=\"#22C55E\" font-size=\"10\" text-anchor=\"middle\">Prog AND</text><text x=\"227\" y=\"90\" fill=\"#CBD5E1\" font-size=\"9\" text-anchor=\"middle\">Fixed OR</text><rect x=\"305\" y=\"20\" width=\"130\" height=\"85\" rx=\"6\" fill=\"#1E293B\" stroke=\"#22C55E\" stroke-width=\"1.5\"/><text x=\"370\" y=\"45\" fill=\"#22C55E\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">PLA</text><text x=\"370\" y=\"72\" fill=\"#22C55E\" font-size=\"10\" text-anchor=\"middle\">Prog AND</text><text x=\"370\" y=\"90\" fill=\"#22C55E\" font-size=\"9\" text-anchor=\"middle\">Prog OR (Flexible)</text></svg>",
